459	    /**
460	     * Voids up to $cap pending commission entries for a specific affiliate-brand pair.
461	     * Returns overflow: true (without voiding) when count exceeds cap — caller should
462	     * dispatch VoidPendingCommissionsForLinkJob instead.
463	     *
464	     * @return array{count: int, total_cents: int, overflow: bool}
465	     */
466	    public function voidPendingForAffiliateBrand(
467	        string $affiliateProfessionalId,
468	        string $brandProfessionalId,
469	        string $reason,
470	        int $cap = 200,
471	    ): array {
472	        $pendingCount = DB::table('commerce.commission_ledger_entries')
473	            ->where('affiliate_professional_id', $affiliateProfessionalId)
474	            ->where('brand_professional_id', $brandProfessionalId)
475	            ->where('status', 'pending')
476	            ->whereNull('payout_id')
477	            ->count();
478	
479	        if ($pendingCount > $cap) {
480	            return ['count' => 0, 'total_cents' => 0, 'overflow' => true];
481	        }
482	
483	        return $this->runVoidLoop($affiliateProfessionalId, $brandProfessionalId, $reason);
484	    }
