486	    /** Loops voidEntry() over every pending entry for the pair. */
487	    public function runVoidLoop(
488	        string $affiliateProfessionalId,
489	        string $brandProfessionalId,
490	        string $reason,
491	    ): array {
492	        $voidedCount = 0;
493	        $voidedCents = 0;
494	
495	        CommissionLedgerEntry::query()
496	            ->where('affiliate_professional_id', $affiliateProfessionalId)
497	            ->where('brand_professional_id', $brandProfessionalId)
498	            ->where('status', 'pending')
499	            ->whereNull('payout_id')
500	            ->orderBy('occurred_at')
501	            ->chunkById(50, function ($entries) use (&$voidedCount, &$voidedCents, $reason): void {
502	                foreach ($entries as $entry) {
503	                    if ($this->voidEntry($entry, $reason)) {
504	                        $voidedCount++;
505	                        $voidedCents += (int) $entry->amount_cents;
506	                    }
507	                }
508	            });
509	
510	        return ['count' => $voidedCount, 'total_cents' => $voidedCents, 'overflow' => false];
511	    }
