513	    /**
514	     * @return array{count: int, total_cents: int}
515	     */
516	    public function pendingSummaryForAffiliateBrand(
517	        string $affiliateProfessionalId,
518	        string $brandProfessionalId,
519	    ): array {
520	        $row = DB::table('commerce.commission_ledger_entries')
521	            ->where('affiliate_professional_id', $affiliateProfessionalId)
522	            ->where('brand_professional_id', $brandProfessionalId)
523	            ->where('status', 'pending')
524	            ->whereNull('payout_id')
525	            ->selectRaw('COUNT(*) AS c, COALESCE(SUM(amount_cents), 0) AS t')
526	            ->first();
527	
528	        return [
529	            'count' => (int) ($row->c ?? 0),
530	            'total_cents' => (int) ($row->t ?? 0),
531	        ];
532	    }
