534	    private function getPendingCommissionCentsBatch(array $affiliateIds): array
535	    {
536	        if ($affiliateIds === []) {
537	            return [];
538	        }
539	
540	        return CommissionLedgerEntry::query()
541	            ->whereNull('payout_id')
542	            ->where('entry_type', 'accrual')
543	            ->where('status', 'pending')
544	            ->whereIn('affiliate_professional_id', $affiliateIds)
545	            ->groupBy('affiliate_professional_id')
546	            ->pluck(\Illuminate\Support\Facades\DB::raw('SUM(amount_cents)'), 'affiliate_professional_id')
547	            ->map(fn ($v) => (int) $v)
548	            ->all();
549	    }
