551	    private function formatMoney(int $cents, string $currencyCode): string
552	    {
553	        $prefix = match (strtoupper($currencyCode)) {
554	            'USD' => '$',
555	            'GBP' => '£',
556	            'EUR' => '€',
557	            'AUD' => 'A$',
558	            default => strtoupper($currencyCode).' ',
559	        };
560	
561	        return $prefix.number_format($cents / 100, 2, '.', ',');
562	    }
563	}
