12	/**
13	 * Handles voiding commissions for affiliates who haven't connected Stripe.
14	 *
15	 * Two phases run on the daily cron:
16	 * 1. processVoidableCommissions() — void entries past their 30-day window
17	 * 2. sendGracePeriodWarnings() — nudge affiliates to connect Stripe
18	 *
19	 * Called from ProcessCommissionPayoutsJob after normal payout processing.
20	 */
21	class CommissionVoidService
22	{
23	    private int $voidWindowDays;
24	
25	    private int $gracePeriodDays;
26	
27	    public function __construct(private readonly NotificationPublisher $publisher)
28	    {
29	        $this->voidWindowDays = (int) config('sidest.store.commission_void_window_days', 30);
30	        $this->gracePeriodDays = (int) config('sidest.store.grace_period_days', 30);
31	    }
