33	    /**
34	     * Find and void all pending commissions past their void window
35	     * for affiliates without active Stripe accounts.
36	     *
37	     * @return array{voided_count: int, voided_cents: int}
38	     */
39	    public function processVoidableCommissions(): array
40	    {
41	        $cutoff = now()->utc()->subDays($this->voidWindowDays);
42	        $stats = ['voided_count' => 0, 'voided_cents' => 0];
43	
44	        // Chunk to avoid OOM on large result sets. Each entry is voided with
45	        // an optimistic lock so a concurrent flush won't be overwritten.
46	        CommissionLedgerEntry::query()
47	            ->whereNull('payout_id')
48	            ->where('entry_type', 'accrual')
49	            ->where('status', 'pending')
50	            ->where('occurred_at', '<=', $cutoff)
51	            ->whereHas('affiliateProfessional', function ($q) {
52	                $q->where('stripe_connect_status', '!=', 'active');
53	            })
54	            ->chunkById(500, function ($entries) use (&$stats) {
55	                foreach ($entries as $entry) {
56	                    try {
57	                        if ($this->voidEntry($entry, 'no_stripe_connected')) {
58	                            $stats['voided_count']++;
59	                            $stats['voided_cents'] += $entry->amount_cents;
60	                        }
61	                    } catch (\Throwable $e) {
62	                        Log::error('Failed to void commission entry', [
63	                            'entry_id' => $entry->id,
64	                            'error' => $e->getMessage(),
65	                        ]);
66	                    }
67	                }
68	            });
69	
70	        if ($stats['voided_count'] > 0) {
71	            Log::info('Commission void processing complete', $stats);
72	        }
73	
74	        return $stats;
75	    }
