77	    /**
78	     * Void a single commission entry. Uses an optimistic lock (WHERE status = pending)
79	     * so a concurrent flush-to-approved from a Stripe webhook can't be overwritten.
80	     *
81	     * @return bool True if the entry was voided, false if it was already claimed.
82	     */
83	    public function voidEntry(CommissionLedgerEntry $entry, string $reason): bool
84	    {
85	        $updated = CommissionLedgerEntry::query()
86	            ->where('id', $entry->id)
87	            ->where('status', 'pending')
88	            ->whereNull('payout_id')
89	            ->update([
90	                'status' => 'voided',
91	                'voided_at' => now(),
92	                'void_reason' => $reason,
93	            ]);
94	
95	        if ($updated === 0) {
96	            Log::info('Skipped voiding commission — status changed concurrently', [
97	                'entry_id' => $entry->id,
98	            ]);
99	
100	            return false;
101	        }
102	
103	        return true;
104	    }
