106	    /**
107	     * Cancel commission payouts whose 60-day grace window has expired
108	     * without the affiliate connecting Stripe Connect.
109	     *
110	     * Scans pending/pending_funds payouts past their void_at via the
111	     * partial index commission_payouts_void_at_idx, then for each one
112	     * checks the affiliate's Stripe status and cancels if not active.
113	     * Linked ledger entries are marked voided in the same transaction so
114	     * the affiliate's ledger UI shows a consistent "expired" state — leaving
115	     * them linked to a cancelled payout would orphan them (never re-eligible
116	     * because the payout creator filters whereNull('payout_id')).
117	     *
118	     * Called from VoidExpiredPayoutsJob (nightly cron).
119	     *
120	     * @return array{cancelled_count: int, cancelled_cents: int, voided_entries: int}
121	     */
122	    public function processExpiredPayouts(): array
123	    {
124	        $stats = ['cancelled_count' => 0, 'cancelled_cents' => 0, 'voided_entries' => 0];
125	
126	        // Pre-fetch inactive affiliate IDs so the main query uses set membership
127	        // (hash join) instead of a correlated per-row EXISTS probe against professionals.
128	        $inactiveAffiliateIds = Professional::query()
129	            ->where('stripe_connect_status', '!=', 'active')
130	            ->pluck('id')
131	            ->all();
132	
133	        if ($inactiveAffiliateIds === []) {
134	            return $stats;
135	        }
136	
137	        CommissionPayout::query()
138	            ->whereIn('status', ['pending', 'pending_funds'])
139	            ->where('void_at', '<', now())
140	            ->whereIn('affiliate_professional_id', $inactiveAffiliateIds)
141	            ->with('brandProfessional:id,display_name')
142	            ->chunkById(200, function ($payouts) use (&$stats): void {
143	                foreach ($payouts as $payout) {
144	                    try {
145	                        $this->cancelExpiredPayout($payout, $stats);
146	                    } catch (\Throwable $e) {
147	                        Log::error('Failed to cancel expired payout', [
148	                            'payout_id' => $payout->id,
149	                            'exception' => $e,
150	                        ]);
151	                    }
152	                }
153	            });
154	
155	        return $stats;
156	    }
157	
158	    /**
159	     * Cancel a single expired payout and void its linked ledger entries.
160	     * Optimistic lock guards against an in-flight ExecuteCommissionPayoutJob
161	     * advancing the status to 'collecting' between the SELECT and UPDATE.
162	     */
163	    private function cancelExpiredPayout(CommissionPayout $payout, array &$stats): void
164	    {
165	        $cancelled = false;
166	
167	        DB::transaction(function () use ($payout, &$stats, &$cancelled): void {
168	            $updated = CommissionPayout::query()
169	                ->where('id', $payout->id)
170	                ->whereIn('status', ['pending', 'pending_funds'])
171	                ->update([
172	                    'status' => 'cancelled',
173	                    'failure_code' => 'grace_period_expired',
174	                    'failure_reason' => 'Affiliate did not connect Stripe Connect within the grace period.',
175	                    'updated_at' => now(),
176	                ]);
177	
178	            if ($updated === 0) {
179	                Log::info('Skipped cancelling expired payout — status changed concurrently', [
180	                    'payout_id' => $payout->id,
181	                ]);
182	
183	                return;
184	            }
185	
186	            $voidedEntries = CommissionLedgerEntry::query()
187	                ->where('payout_id', $payout->id)
188	                ->whereIn('status', ['pending', 'approved'])
189	                ->update([
190	                    'status' => 'voided',
191	                    'voided_at' => now(),
192	                    'void_reason' => 'payout_grace_expired',
193	                    'updated_at' => now(),
194	                ]);
195	
196	            $stats['cancelled_count']++;
197	            $stats['cancelled_cents'] += (int) $payout->gross_commission_cents;
198	            $stats['voided_entries'] += (int) $voidedEntries;
199	            $cancelled = true;
200	        });
201	
202	        if ($cancelled) {
203	            $this->publisher->publish(
204	                professionalId: $payout->affiliate_professional_id,
205	                frontendType: 'Warning',
206	                category: 'commissions',
207	                title: 'Commission payout expired',
208	                body: sprintf(
209	                    'Your %s payout from %s has been cancelled because Stripe Connect was not activated within the grace period.',
210	                    $this->formatMoney($payout->net_payout_cents, $payout->currency_code),
211	                    $payout->brandProfessional?->display_name ?? 'a brand',
212	                ),
213	                dedupeKey: "payout_voided.{$payout->id}",
214	                ctaUrl: '/account/settings?section=stripe',
215	                retentionConfigKey: 'commission',
216	            );
217	        }
218	    }
