372	                'range' => [now()->addDays(2)->startOfDay(), now()->addDays(2)->endOfDay()],
373	                'title' => 'Connect Stripe — 2 days left',
374	                'body' => '2 days left — connect Stripe now or your %s payout will be cancelled.',
375	            ],
376	        ];
377	
378	        // Pre-fetch once for both warning windows (day 10 and day 2) to avoid
379	        // a correlated subquery on each chunk pass.
380	        $inactiveAffiliateIds = Professional::query()
381	            ->where('stripe_connect_status', '!=', 'active')
382	            ->pluck('id')
383	            ->all();
384	
385	        if ($inactiveAffiliateIds === []) {
386	            return $sent;
387	        }
388	
389	        foreach ($warningWindows as $key => $window) {
390	            CommissionPayout::query()
391	                ->whereIn('status', ['pending', 'pending_funds'])
392	                ->whereBetween('void_at', $window['range'])
393	                ->whereIn('affiliate_professional_id', $inactiveAffiliateIds)
394	                ->chunkById(200, function ($payouts) use (&$sent, $key, $window): void {
395	                    foreach ($payouts as $payout) {
396	                        $this->publisher->publish(
397	                            professionalId: $payout->affiliate_professional_id,
398	                            frontendType: 'Warning',
399	                            category: 'commissions',
400	                            title: $window['title'],
401	                            body: sprintf($window['body'], $this->formatMoney($payout->net_payout_cents, $payout->currency_code)),
402	                            dedupeKey: "stripe_warning.payout.{$key}.{$payout->id}",
403	                            ctaUrl: '/account/settings?section=stripe',
404	                            retentionConfigKey: 'commission',
405	                        );
406	                        $sent++;
407	                    }
408	                });
409	        }
410	
411	        return $sent;
412	    }
413	
414	    /**
415	     * Flush eligible held commissions when an affiliate connects Stripe.
416	     * Called from the webhook handler when status transitions to 'active'.
417	     *
418	     * Finds all pending commissions for this affiliate where the void window
419	     * hasn't expired, then marks them approved so the normal payout cron
420	     * picks them up.
421	     *
422	     * @return int Number of commissions flushed to approved
423	     */
424	    public function flushHeldCommissions(Professional $affiliate): int
425	    {
426	        $count = CommissionLedgerEntry::query()
427	            ->whereNull('payout_id')
428	            ->where('entry_type', 'accrual')
429	            ->where('status', 'pending')
430	            ->where('affiliate_professional_id', $affiliate->id)
431	            ->where('occurred_at', '>', now()->utc()->subDays($this->voidWindowDays))
432	            ->update(['status' => 'approved']);
433	
434	        if ($count > 0) {
435	            Log::info('Flushed held commissions on Stripe connect', [
436	                'affiliate_id' => $affiliate->id,
437	                'count' => $count,
438	            ]);
439	        }
440	
441	        return $count;
442	    }
443	
444	    /**
445	     * Check if an affiliate is within their grace period (Stripe not yet required).
446	     */
447	    public function isInGracePeriod(Professional $affiliate): bool
448	    {
449	        return $affiliate->stripe_grace_period_ends_at !== null
450	            && $affiliate->stripe_grace_period_ends_at->isFuture();
451	    }
452	
453	    /**
454	     * Batch-load pending commission totals for multiple affiliates in one query.
455	     *
456	     * @param  string[]  $affiliateIds
457	     * @return array<string, int> affiliate_id => total_pending_cents
458	     */
459	    /**
460	     * Voids up to $cap pending commission entries for a specific affiliate-brand pair.
461	     * Returns overflow: true (without voiding) when count exceeds cap — caller should
462	     * dispatch VoidPendingCommissionsForLinkJob instead.
463	     *
464	     * @return array{count: int, total_cents: int, overflow: bool}
465	     */
466	    public function voidPendingForAffiliateBrand(
467	        string $affiliateProfessionalId,
468	        string $brandProfessionalId,
469	        string $reason,
470	        int $cap = 200,
471	    ): array {
472	        $pendingCount = DB::table('commerce.commission_ledger_entries')
473	            ->where('affiliate_professional_id', $affiliateProfessionalId)
474	            ->where('brand_professional_id', $brandProfessionalId)
475	            ->where('status', 'pending')
476	            ->whereNull('payout_id')
477	            ->count();
478	
479	        if ($pendingCount > $cap) {
480	            return ['count' => 0, 'total_cents' => 0, 'overflow' => true];
481	        }
482	
483	        return $this->runVoidLoop($affiliateProfessionalId, $brandProfessionalId, $reason);
484	    }
485	
486	    /** Loops voidEntry() over every pending entry for the pair. */
487	    public function runVoidLoop(
488	        string $affiliateProfessionalId,
489	        string $brandProfessionalId,
490	        string $reason,
491	    ): array {
492	        $voidedCount = 0;
493	        $voidedCents = 0;
494	
495	        CommissionLedgerEntry::query()
496	            ->where('affiliate_professional_id', $affiliateProfessionalId)
497	            ->where('brand_professional_id', $brandProfessionalId)
498	            ->where('status', 'pending')
499	            ->whereNull('payout_id')
500	            ->orderBy('occurred_at')
501	            ->chunkById(50, function ($entries) use (&$voidedCount, &$voidedCents, $reason): void {
502	                foreach ($entries as $entry) {
503	                    if ($this->voidEntry($entry, $reason)) {
504	                        $voidedCount++;
505	                        $voidedCents += (int) $entry->amount_cents;
506	                    }
507	                }
508	            });
509	
510	        return ['count' => $voidedCount, 'total_cents' => $voidedCents, 'overflow' => false];
511	    }
512	
513	    /**
514	     * @return array{count: int, total_cents: int}
515	     */
516	    public function pendingSummaryForAffiliateBrand(
517	        string $affiliateProfessionalId,
518	        string $brandProfessionalId,
519	    ): array {
520	        $row = DB::table('commerce.commission_ledger_entries')
521	            ->where('affiliate_professional_id', $affiliateProfessionalId)
522	            ->where('brand_professional_id', $brandProfessionalId)
523	            ->where('status', 'pending')
524	            ->whereNull('payout_id')
525	            ->selectRaw('COUNT(*) AS c, COALESCE(SUM(amount_cents), 0) AS t')
526	            ->first();
527	
528	        return [
529	            'count' => (int) ($row->c ?? 0),
530	            'total_cents' => (int) ($row->t ?? 0),
531	        ];
532	    }
533	
534	    private function getPendingCommissionCentsBatch(array $affiliateIds): array
535	    {
536	        if ($affiliateIds === []) {
537	            return [];
538	        }
539	
540	        return CommissionLedgerEntry::query()
541	            ->whereNull('payout_id')
542	            ->where('entry_type', 'accrual')
543	            ->where('status', 'pending')
544	            ->whereIn('affiliate_professional_id', $affiliateIds)
545	            ->groupBy('affiliate_professional_id')
546	            ->pluck(\Illuminate\Support\Facades\DB::raw('SUM(amount_cents)'), 'affiliate_professional_id')
547	            ->map(fn ($v) => (int) $v)
548	            ->all();
549	    }
550	
551	    private function formatMoney(int $cents, string $currencyCode): string
552	    {
553	        $prefix = match (strtoupper($currencyCode)) {
554	            'USD' => '$',
555	            'GBP' => '£',
556	            'EUR' => '€',
557	            'AUD' => 'A$',
558	            default => strtoupper($currencyCode).' ',
559	        };
560	
561	        return $prefix.number_format($cents / 100, 2, '.', ',');
562	    }
563	}
