3	namespace App\Services\Notifications;
4	
5	use App\Jobs\Notifications\SendTransactionalNotificationEmailJob;
6	use App\Models\Core\Notifications\Notification;
7	use Illuminate\Support\Facades\DB;
8	use Illuminate\Support\Str;
9	
10	// V2: Core notification engine. Publishes with atomic dedup via dedupe_key column,
11	// optional email dispatch, retention policies, and per-professional category overrides.
12	class NotificationPublisher
13	{
14	    /**
15	     * Valid category keys — derived from the single source of truth in
16	     * config/sidest.php. FormRequests and controllers should prefer calling
17	     * this method directly over importing a constant.
18	     *
19	     * @return array<int, string>
20	     */
21	    public static function categories(): array
22	    {
23	        return array_keys((array) config('sidest.notifications.mailables', []));
24	    }
25	
26	    public function publish(
27	        string $professionalId,
28	        string $frontendType,
29	        string $category,
30	        string $title,
31	        string $body,
32	        string $dedupeKey,
33	        ?string $ctaUrl = null,
34	        ?string $primaryActionLabel = 'View',
35	        ?string $secondaryActionLabel = 'Dismiss',
36	        ?string $secondaryActionUrl = null,
37	        ?string $retentionConfigKey = null,
38	    ): void {
39	        $professionalId = trim($professionalId);
40	        if ($professionalId === '') {
41	            return;
42	        }
43	
44	        $title = trim($title);
45	        $body = trim($body);
46	        if ($title === '' || $body === '') {
47	            return;
48	        }
49	
50	        $dedupeKey = trim($dedupeKey);
51	        if ($dedupeKey === '') {
52	            // Require a non-empty dedupe key — callers should always provide one.
53	            return;
54	        }
55	
56	        $now = now();
57	        $type = Notification::normalizeFrontendType($frontendType);
58	        $retentionKey = $retentionConfigKey ?? 'default';
59	        $days = config("sidest.notification_retention_days.{$retentionKey}")
60	            ?? config('sidest.notification_retention_days.default', 30);
61	
62	        $notificationId = (string) Str::uuid();
63	
64	        // Atomic upsert: ON CONFLICT on (professional_id, dedupe_key) DO NOTHING.
65	        // If a notification with this dedupe_key already exists for this pro,
66	        // this is a no-op — no duplicate row, no race window.
67	        $inserted = DB::table('notifications.notifications')->insertOrIgnore([
68	            'id' => $notificationId,
69	            'professional_id' => $professionalId,
70	            'type' => $type,
71	            'category' => $category,
72	            'title' => $title,
73	            'body' => $body,
74	            'cta_url' => $ctaUrl ?? '/account/overview',
75	            'primary_action_label' => $primaryActionLabel,
76	            'secondary_action_label' => $secondaryActionLabel,
77	            'secondary_action_url' => $secondaryActionUrl,
78	            'severity' => Notification::severityForFrontendType($type),
79	            'starts_at' => $now,
80	            'ends_at' => $now->copy()->addDays((int) $days),
81	            'dedupe_key' => $dedupeKey,
82	            'created_at' => $now,
83	            'updated_at' => $now,
84	        ]);
85	
86	        // Only dispatch the email job for genuinely-new rows. insertOrIgnore()
87	        // returns the number of rows actually inserted (0 on conflict).
88	        if ($inserted > 0 && config('sidest.notifications.email_enabled', false)) {
89	            SendTransactionalNotificationEmailJob::dispatch(
90	                $notificationId,
91	                $category,
92	                $professionalId,
93	            )->onQueue('mail');
94	        }
95	    }
96	
97	    public static function resolveEmailEnabled(string $professionalId, string $category): bool
98	    {
99	        // Per-professional policy
100	        $perProMode = DB::table('core.notification_email_policies')
101	            ->where('professional_id', $professionalId)
102	            ->where('category_key', $category)
103	            ->value('mode');
104	
105	        if ($perProMode === 'force_on') {
106	            return true;
107	        }
108	        if ($perProMode === 'force_off') {
109	            return false;
110	        }
111	
112	        // Global policy
113	        $globalMode = DB::table('core.notification_email_policies')
114	            ->whereNull('professional_id')
115	            ->where('category_key', $category)
116	            ->value('mode');
117	
118	        if ($globalMode === 'force_on') {
119	            return true;
120	        }
121	        if ($globalMode === 'force_off') {
122	            return false;
123	        }
124	
125	        // Professional preference
126	        $preference = DB::table('notifications.notification_email_preferences')
127	            ->where('professional_id', $professionalId)
128	            ->where('category_key', $category)
129	            ->value('enabled');
130	
131	        if ($preference !== null) {
132	            return (bool) $preference;
133	        }
134	
135	        return true; // default enabled
136	    }
137	}
