3	namespace App\Services\Stripe;
4	
5	use App\Jobs\Stripe\ExecuteCommissionPayoutJob;
6	use App\Models\Core\Professional\Professional;
7	use App\Models\Retail\BrandStoreSettings;
8	use App\Models\Retail\CommissionLedgerEntry;
9	use App\Models\Retail\CommissionPayout;
10	use App\Models\Retail\CommissionPayoutItem;
11	use Illuminate\Support\Facades\DB;
12	use Illuminate\Support\Facades\Log;
13	use Stripe\Exception\ApiConnectionException;
14	use Stripe\Exception\ApiErrorException;
15	use Stripe\Exception\RateLimitException;
16	use Stripe\StripeClient;
17	
18	// V2: Core. Processes eligible commission payouts with hybrid funding (wallet balance first, card charge for shortfall). Transfers net amount to affiliate via Stripe Connect (80/20 split).
19	class CommissionPayoutService
20	{
21	    private StripeClient $stripe;
22	
23	    private float $platformFeePercent;
24	
25	    private int $systemHoldDays;
26	
27	    private int $minHoldDays;
28	
29	    private int $gracePeriodDays;
30	
31	    public function __construct(?StripeClient $stripe = null)
32	    {
33	        $this->stripe = $stripe ?? new StripeClient(config('services.stripe.secret_key'));
34	        $this->platformFeePercent = config('sidest.store.platform_fee_percent', 3);
35	        $this->systemHoldDays = max(0, (int) config('sidest.store.payout_hold_days', 7));
36	        $this->minHoldDays = (int) config('sidest.store.min_payout_hold_days', 7);
37	        // Clamp to [1, 365] — values outside this range produce nonsensical void_at timestamps.
38	        $this->gracePeriodDays = max(1, min(365, (int) config('sidest.store.grace_period_days', 60)));
39	    }
40	
41	    /**
42	     * Main entry point: find all eligible unpaid commissions, batch them,
43	     * and dispatch a per-payout job for each. Returns dispatch counts only —
44	     * actual results are reported per-job via Horizon.
45	     *
46	     * @return array{batches_dispatched: int, batches_created: int, batches_requeued: int}
47	     */
48	    public function processEligiblePayouts(): array
49	    {
50	        $stats = [
51	            'batches_dispatched' => 0,
52	            'batches_created' => 0,
53	            'batches_requeued' => 0,
54	        ];
55	
56	        // Re-dispatch any in-flight batches. ExecuteCommissionPayoutJob's idempotent
57	        // resume logic handles collecting/transferring states safely.
58	        $existingPending = CommissionPayout::query()
59	            ->whereIn('status', ['pending', 'pending_funds', 'collecting', 'transferring'])
60	            ->whereNull('processed_at')
61	            ->where('eligible_after', '<=', now())
62	            ->orderBy('eligible_after')
63	            ->limit(500)
64	            ->get();
65	
66	        foreach ($existingPending as $pendingPayout) {
67	            ExecuteCommissionPayoutJob::dispatch($pendingPayout->id);
68	            $stats['batches_dispatched']++;
69	            $stats['batches_requeued']++;
70	        }
71	
72	        // Find all brands that have unpaid approved accruals, then apply
73	        // per-brand hold days to determine which entries are eligible.
74	        $brandIds = CommissionLedgerEntry::query()
75	            ->whereNull('payout_id')
76	            ->where('entry_type', 'accrual')
77	            ->where('status', 'approved')
78	            ->distinct()
79	            ->pluck('brand_professional_id');
80	
81	        // Pre-load brand store settings for hold-day lookups.
82	        $brandSettings = BrandStoreSettings::query()
83	            ->whereIn('professional_id', $brandIds)
84	            ->pluck('payout_hold_days', 'professional_id');
85	
86	        foreach ($brandIds as $brandId) {
87	            $holdDays = $this->resolveHoldDays($brandSettings[$brandId] ?? null);
88	            $cutoff = now()->utc()->subDays($holdDays);
89	
90	            $groups = CommissionLedgerEntry::query()
91	                ->whereNull('payout_id')
92	                ->where('entry_type', 'accrual')
93	                ->where('status', 'approved')
94	                ->where('brand_professional_id', $brandId)
95	                ->where('occurred_at', '<=', $cutoff)
96	                ->select([
97	                    'brand_professional_id',
98	                    'affiliate_professional_id',
99	                    'currency_code',
100	                    DB::raw('SUM(amount_cents) as total_cents'),
101	                    DB::raw('COUNT(*) as entry_count'),
102	                ])
103	                ->groupBy('brand_professional_id', 'affiliate_professional_id', 'currency_code')
104	                ->having(DB::raw('SUM(amount_cents)'), '>', 0)
105	                ->get();
106	
107	            foreach ($groups as $group) {
108	                try {
109	                    $payout = $this->createPayoutBatch(
110	                        $group->brand_professional_id,
111	                        $group->affiliate_professional_id,
112	                        $group->currency_code,
113	                        $cutoff,
114	                    );
115	
116	                    if (! $payout) {
117	                        continue;
118	                    }
119	
120	                    $stats['batches_created']++;
121	                    ExecuteCommissionPayoutJob::dispatch($payout->id);
122	                    $stats['batches_dispatched']++;
123	                } catch (\Throwable $e) {
124	                    Log::error('Commission payout batch creation failed', [
125	                        'brand_id' => $group->brand_professional_id,
126	                        'affiliate_id' => $group->affiliate_professional_id,
127	                        'currency' => $group->currency_code,
128	                        'error' => $e instanceof ApiErrorException ? ($e->getStripeCode() ?? 'stripe_error') : get_class($e),
129	                    ]);
130	                }
131	            }
132	        }
133	
134	        return $stats;
135	    }
136	
137	    /**
138	     * Resolve the effective hold days for a brand.
139	     * Uses brand override if set, otherwise system default. Always >= system minimum.
140	     */
141	    private function resolveHoldDays(?int $brandPayoutHoldDays): int
142	    {
143	        $days = $brandPayoutHoldDays ?? $this->systemHoldDays;
144	
145	        return max($this->minHoldDays, $days);
146	    }
147	
148	    /**
149	     * Create a payout batch record and link all eligible ledger entries.
150	     */
151	    private function createPayoutBatch(
152	        string $brandId,
153	        string $affiliateId,
154	        string $currency,
155	        \DateTimeInterface $cutoff,
156	    ): ?CommissionPayout {
157	        // READ COMMITTED (PG default) — lockForUpdate() on both reads is sufficient
158	        // to prevent a concurrent batch from claiming the same ledger entries.
159	        return DB::transaction(function () use ($brandId, $affiliateId, $currency, $cutoff) {
160	            $entries = CommissionLedgerEntry::query()
161	                ->whereNull('payout_id')
162	                ->where('entry_type', 'accrual')
163	                ->where('status', 'approved')
164	                ->where('brand_professional_id', $brandId)
165	                ->where('affiliate_professional_id', $affiliateId)
166	                ->where('currency_code', $currency)
167	                ->where('occurred_at', '<=', $cutoff)
168	                ->lockForUpdate()
169	                ->get();
170	
171	            if ($entries->isEmpty()) {
172	                return null;
173	            }
174	
175	            $grossCents = $entries->sum('amount_cents');
176	            if ($grossCents <= 0) {
177	                return null;
178	            }
179	
180	            // Single locked fetch — reused for both the net-commission sum
181	            // below and the foreach that links these entries to the payout.
182	            // lockForUpdate matches the accrual fetch above and closes the
183	            // race where a reversal could land between SUM and GET.
184	            $reversals = CommissionLedgerEntry::query()
185	                ->whereNull('payout_id')
186	                ->where('entry_type', 'reversal')
187	                ->where('status', 'approved')
188	                ->where('brand_professional_id', $brandId)
189	                ->where('affiliate_professional_id', $affiliateId)
190	                ->where('currency_code', $currency)
191	                ->where('occurred_at', '<=', $cutoff)
192	                ->lockForUpdate()
193	                ->get();
194	
195	            $reversalCents = (int) $reversals->sum('amount_cents');
196	            $netCommission = $grossCents + $reversalCents;
197	            if ($netCommission <= 0) {
198	                return null;
199	            }
200	
201	            $platformFeeCents = (int) round($netCommission * $this->platformFeePercent / 100);
202	            $netPayoutCents = $netCommission - $platformFeeCents;
203	
204	            if ($netPayoutCents <= 0) {
205	                return null;
206	            }
207	
208	            // Per-payout grace window — 60d from creation. If the affiliate
209	            // hasn't activated Stripe Connect by then, VoidExpiredPayoutsJob
210	            // cancels this payout and voids its ledger entries.
211	            // grace_period_days lives in config/sidest.php so ops can tune
212	            // the policy without a code release.
213	            $payout = CommissionPayout::forceCreate([
214	                'brand_professional_id' => $brandId,
215	                'affiliate_professional_id' => $affiliateId,
216	                'status' => 'pending',
217	                'gross_commission_cents' => $netCommission,
218	                'platform_fee_cents' => $platformFeeCents,
219	                'net_payout_cents' => $netPayoutCents,
220	                'currency_code' => strtoupper($currency),
221	                'ledger_entry_count' => $entries->count(),
222	                'eligible_after' => $cutoff,
223	                'void_at' => DB::raw("NOW() + INTERVAL '{$this->gracePeriodDays} days'"),
224	                'funding_source' => null,
225	            ]);
226	
227	            foreach ($entries as $entry) {
228	                CommissionPayoutItem::create([
229	                    'payout_id' => $payout->id,
230	                    'commission_ledger_entry_id' => $entry->id,
231	                    'amount_cents' => $entry->amount_cents,
232	                ]);
233	                $entry->forceFill(['payout_id' => $payout->id])->save();
234	            }
235	
236	            foreach ($reversals as $reversal) {
237	                CommissionPayoutItem::create([
238	                    'payout_id' => $payout->id,
239	                    'commission_ledger_entry_id' => $reversal->id,
240	                    'amount_cents' => $reversal->amount_cents,
241	                ]);
242	                $reversal->forceFill(['payout_id' => $payout->id])->save();
243	            }
244	
245	            return $payout;
246	        });
247	    }
248	
249	    /**
250	     * Process a single payout through the full 3-step flow with idempotent resume:
251	     *   1) Debit wallet balance (atomic with status update — crash-safe).
252	     *   2) Charge brand's card for any shortfall.
253	     *   3) Transfer net amount to affiliate via Stripe Connect.
254	     *
255	     * Each step checks the payout's current status before executing, so retries
256	     * (both Horizon automatic and admin manual) resume from where they left off
257	     * rather than restarting from scratch. This prevents double-debiting the wallet
258	     * and double-charging the brand's card.
259	     *
260	     * Return values:
261	     * - true:  completed
262	     * - null:  pending for funding/retry
263	     * - false: failed
264	     */
265	    public function processPayoutBatch(CommissionPayout $payout): ?bool
266	    {
267	        if ($payout->status === 'completed') {
268	            return true;
269	        }
270	
271	        $brand = Professional::find($payout->brand_professional_id);
272	        $affiliate = Professional::find($payout->affiliate_professional_id);
273	
274	        if (! $affiliate?->stripe_connect_account_id || $affiliate->stripe_connect_status !== 'active') {
275	            $this->markPendingFunding($payout, 'affiliate_not_connected', 'Affiliate Stripe Connect account is not active — holding for grace period');
276	
277	            return null;
278	        }
279	
280	        if (! $brand) {
281	            $this->failPayout($payout, 'brand_missing', 'Brand account was not found.');
