299	
300	        // Idempotency key suffix used only for PaymentIntents — retry_count is incremented
301	        // on each admin manual retry so a fresh PI is created rather than returning a
302	        // refunded/failed one from within the 24-hour idempotency TTL window.
303	        // Transfers intentionally use a stable key (no suffix) so Stripe returns the same
304	        // transfer on any retry, preventing a duplicate payout if the transfer succeeded
305	        // but the HTTP response was lost before the ID could be recorded.
306	        $retryKey = '_r'.$payout->retry_count;
