308	        // Step 1: Wallet debit — or resume from recorded state
309	        //
310	        // The debit and the status update are wrapped in a single DB::transaction
311	        // so a process crash between them can't leave the wallet reduced but the
312	        // payout record still showing 'pending' (which would cause a double-debit on retry).
313	        $walletDebitCents = 0;
314	        $chargeAmountCents = $amountToCollect;
315	
316	        if (in_array($payout->status, ['collecting', 'collected', 'transferring'], true)) {
317	            // Wallet debit already committed in a previous run — read from DB, don't re-debit.
318	            $walletDebitCents = (int) ($payout->wallet_debit_cents ?? 0);
319	            $chargeAmountCents = (int) ($payout->charge_cents ?? $amountToCollect);
320	        } else {
