322	            // are atomic here; lockForUpdate() inside debitBrandManualBalancePartial
323	            // guards against concurrent debits on the wallet row itself.
324	            DB::transaction(function () use ($payout, $brand, $amountToCollect, $currencyUpper, &$walletDebitCents, &$chargeAmountCents): void {
325	                $walletDebitCents = $this->debitBrandManualBalancePartial($brand->id, $amountToCollect, $currencyUpper);
326	                $chargeAmountCents = $amountToCollect - $walletDebitCents;
327	
328	                $fundingSource = 'card';
329	                if ($walletDebitCents > 0 && $chargeAmountCents > 0) {
330	                    $fundingSource = 'wallet_and_card';
331	                } elseif ($walletDebitCents > 0) {
332	                    $fundingSource = 'wallet';
333	                }
