335	                $payout->forceFill([
336	                    'status' => 'collecting',
337	                    'funding_source' => $fundingSource,
338	                    'wallet_debit_cents' => $walletDebitCents,
339	                    'charge_cents' => $chargeAmountCents,
340	                    'failure_code' => null,
341	                    'failure_reason' => null,
342	                ])->save();
343	            });
344	        }
345	
346	        // Step 2: Charge brand's card for the shortfall (if any)
347	        $latestChargeId = null;
