358	                $paymentIntent = $this->stripe->paymentIntents->create([
359	                    'amount' => $chargeAmountCents,
360	                    'currency' => $currencyLower,
361	                    'customer' => $brand->stripe_customer_id,
362	                    'payment_method' => $brand->stripe_payment_method_id,
363	                    'confirm' => true,
364	                    'off_session' => true,
365	                    'description' => "Commission payout #{$payout->id}",
366	                    'metadata' => [
