397	                // Wallet debit is already committed in 'collecting' status; the
398	                // idempotent resume will skip re-debiting on the next attempt.
399	                throw $e;
400	            } catch (ApiErrorException $e) {
401	                // Terminal card failure (declined, invalid PM, SCA permanently blocked, etc.)
