407	                return null;
408	            }
409	        } else {
410	            // Fully funded by wallet — only advance status if not already past this step
411	            if (! in_array($payout->status, ['collected', 'transferring'], true)) {
412	                $payout->forceFill(['status' => 'collected'])->save();
413	            }
414	        }
415	
416	        // Step 3: Transfer net amount to the affiliate's Connect account
417	        try {
418	            if ($payout->status !== 'transferring') {
419	                $payout->forceFill(['status' => 'transferring'])->save();
