423	            // (e.g. the transfer was saved but the server crashed before marking complete).
424	            if (! $payout->stripe_transfer_id) {
425	                $transferPayload = [
426	                    'amount' => $payout->net_payout_cents,
427	                    'currency' => $currencyLower,
428	                    'destination' => $affiliate->stripe_connect_account_id,
429	                    'description' => "Commission payout #{$payout->id} to {$affiliate->display_name}",
430	                    'metadata' => [
431	                        'sidest_payout_id' => $payout->id,
432	                        'brand_id' => $brand->id,
433	                        'affiliate_id' => $affiliate->id,
434	                    ],
435	                ];
436	
437	                if ($latestChargeId) {
438	                    $transferPayload['source_transaction'] = $latestChargeId;
439	                }
440	
441	                $transfer = $this->stripe->transfers->create(
442	                    $transferPayload,
443	                    // Stable key — no retry_count suffix. Stripe returns the same transfer
444	                    // on any retry (including admin retries that increment retry_count),
445	                    // preventing a duplicate payout when the transfer succeeded but the
446	                    // response was lost before stripe_transfer_id could be recorded.
447	                    ['idempotency_key' => 'tr_'.$payout->id]
