455	            $payout->forceFill([
456	                'status' => 'completed',
457	                'processed_at' => now(),
458	                'failure_code' => null,
459	                'failure_reason' => null,
460	            ])->save();
461	
462	            Log::info('Commission payout completed', [
463	                'payout_id' => $payout->id,
464	                'gross_cents' => $payout->gross_commission_cents,
465	                'wallet_debit_cents' => $walletDebitCents,
466	                'charge_cents' => $chargeAmountCents,
467	                'platform_fee_cents' => $payout->platform_fee_cents,
468	                'net_cents' => $payout->net_payout_cents,
469	                'funding_source' => $payout->funding_source,
470	                'currency' => $payout->currency_code,
471	            ]);
