526	    /**
527	     * Debit the brand's wallet balance, up to the requested amount (partial OK).
528	     * Returns the actual amount debited (0 if no balance available).
529	     */
530	    private function debitBrandManualBalancePartial(string $brandId, int $requestedCents, string $currencyCode): int
531	    {
532	        if ($requestedCents <= 0) {
533	            return 0;
534	        }
535	
536	        // READ COMMITTED (PG default) — lockForUpdate() on the professional row
537	        // serialises concurrent debits; no higher isolation level is required.
538	        return DB::transaction(function () use ($brandId, $requestedCents, $currencyCode) {
539	            $brand = Professional::query()
540	                ->whereKey($brandId)
541	                ->lockForUpdate()
542	                ->first();
543	
544	            if (! $brand) {
545	                return 0;
546	            }
547	
548	            $balance = max(0, (int) ($brand->stripe_manual_balance_cents ?? 0));
549	            $walletCurrency = strtoupper((string) ($brand->stripe_manual_balance_currency ?: $currencyCode));
550	
551	            if ($walletCurrency !== strtoupper($currencyCode) || $balance <= 0) {
552	                return 0;
553	            }
554	
555	            $debit = min($balance, $requestedCents);
556	            $brand->stripe_manual_balance_cents = $balance - $debit;
557	            $brand->save();
558	
559	            return $debit;
560	        });
561	    }
562	
563	    public function creditBrandManualBalance(string $brandId, int $amountCents, string $currencyCode): void
564	    {
565	        if ($amountCents <= 0) {
566	            return;
567	        }
568	
569	        // READ COMMITTED (PG default) — lockForUpdate() serialises concurrent credits.
570	        DB::transaction(function () use ($brandId, $amountCents, $currencyCode) {
571	            $brand = Professional::query()
572	                ->whereKey($brandId)
573	                ->lockForUpdate()
574	                ->first();
575	
576	            if (! $brand) {
577	                return;
578	            }
579	
580	            $balance = (int) ($brand->stripe_manual_balance_cents ?? 0);
581	            $brand->stripe_manual_balance_cents = $balance + $amountCents;
582	            $brand->stripe_manual_balance_currency = strtoupper((string) ($brand->stripe_manual_balance_currency ?: $currencyCode));
583	            $brand->save();
584	        });
585	    }
586	
587	    private function extractLatestChargeId(object $paymentIntent): ?string
588	    {
589	        if (is_string($paymentIntent->latest_charge ?? null) && $paymentIntent->latest_charge !== '') {
590	            return $paymentIntent->latest_charge;
591	        }
592	
593	        if (is_object($paymentIntent->latest_charge ?? null) && is_string($paymentIntent->latest_charge->id ?? null)) {
594	            return $paymentIntent->latest_charge->id;
595	        }
596	
597	        if (is_object($paymentIntent->charges ?? null) && is_array($paymentIntent->charges->data ?? null)) {
598	            foreach ($paymentIntent->charges->data as $charge) {
599	                if (is_object($charge) && is_string($charge->id ?? null) && $charge->id !== '') {
600	                    return $charge->id;
601	                }
602	            }
603	        }
604	
605	        return null;
606	    }
607	
608	    private function markPendingFunding(CommissionPayout $payout, string $code, string $reason): void
609	    {
610	        $payout->forceFill([
611	            'status' => 'pending_funds',
612	            'failure_code' => $code,
613	            'failure_reason' => $reason,
614	            'processed_at' => null,
615	        ])->save();
616	
617	        Log::notice('Commission payout pending funding', [
618	            'payout_id' => $payout->id,
619	            'code' => $code,
620	            'reason' => $reason,
621	        ]);
622	    }
623	
624	    private function failPayout(CommissionPayout $payout, string $code, string $reason): void
625	    {
626	        $payout->forceFill([
627	            'status' => 'failed',
628	            'failure_code' => $code,
629	            'failure_reason' => $reason,
630	        ])->save();
631	
632	        Log::warning('Commission payout failed', [
633	            'payout_id' => $payout->id,
634	            'code' => $code,
635	            'reason' => $reason,
636	        ]);
637	    }
