639	    /**
640	     * Manually retry a stuck payout batch (admin endpoint).
641	     *
642	     * Increments retry_count so a fresh Stripe idempotency key is used —
643	     * prevents Stripe returning a refunded/failed PI from within the 24h TTL window.
644	     *
645	     * Blocked for transfer_failed_refund_needed: the auto-refund itself failed, so
646	     * the brand may still be charged. Manual verification is required before retrying.
647	     *
648	     * Runs synchronously so the admin sees the result immediately.
649	     */
650	    public function retryPayout(CommissionPayout $payout): bool
651	    {
652	        if (! in_array($payout->status, ['failed', 'pending', 'pending_funds'], true)) {
653	            return false;
654	        }
655	
656	        // Auto-refund failed — manual verification required before retrying to avoid double-charging.
657	        if ($payout->failure_code === 'transfer_failed_refund_needed') {
658	            return false;
659	        }
660	
661	        // If the wallet was already debited in a previous run, resume from 'collecting'
662	        // so processPayoutBatch() enters its idempotent resume branch and skips
663	        // re-debiting. Resetting to 'pending' would bypass that branch and double-debit.
664	        $resumeStatus = ((int) ($payout->wallet_debit_cents ?? 0)) > 0 ? 'collecting' : 'pending';
665	
666	        $payout->forceFill([
667	            'status' => $resumeStatus,
668	            'failure_code' => null,
669	            'failure_reason' => null,
670	            'needs_manual_refund' => false,
671	            'retry_count' => ($payout->retry_count ?? 0) + 1,
672	        ])->save();
673	
674	        return $this->processPayoutBatch($payout) === true;
675	    }
676	
677	    /**
678	     * Get payout summary for a professional (as brand or affiliate).
679	     */
680	    public function getPayoutSummary(Professional $professional): array
681	    {
682	        $asBrand = CommissionPayout::query()
683	            ->where('brand_professional_id', $professional->id)
684	            ->selectRaw('status, COUNT(*) as count, SUM(gross_commission_cents) as total_cents')
685	            ->groupBy('status')
686	            ->get()
687	            ->keyBy('status');
688	
689	        $asAffiliate = CommissionPayout::query()
690	            ->where('affiliate_professional_id', $professional->id)
691	            ->selectRaw('status, COUNT(*) as count, SUM(net_payout_cents) as total_cents')
692	            ->groupBy('status')
693	            ->get()
694	            ->keyBy('status');
695	
696	        return [
697	            'as_brand' => $asBrand,
698	            'as_affiliate' => $asAffiliate,
699	        ];
700	    }
701	}
